BEGIN;

-- A richer, repeatable showcase dataset for dashboard rankings and business workflows.
-- Fixed identifiers prevent duplicates; relative timestamps keep the dashboard current
-- whenever the development seed is explicitly rerun.

ON CONFLICT (id) DO UPDATE SET
  type=EXCLUDED.type, name=EXCLUDED.name, phone=EXCLUDED.phone, email=EXCLUDED.email,
  address=EXCLUDED.address, credit_limit=EXCLUDED.credit_limit, active=true, updated_at=now();

ON CONFLICT (id) DO UPDATE SET
  customer_id=EXCLUDED.customer_id, status=EXCLUDED.status, subtotal=EXCLUDED.subtotal,
  discount_total=EXCLUDED.discount_total, shipping_total=EXCLUDED.shipping_total,
  tax_total=EXCLUDED.tax_total, grand_total=EXCLUDED.grand_total,
  amount_paid=EXCLUDED.amount_paid, notes=EXCLUDED.notes, placed_at=EXCLUDED.placed_at, updated_at=now();

ON CONFLICT (id) DO UPDATE SET
  quantity=EXCLUDED.quantity, unit_price=EXCLUDED.unit_price,
  unit_cost_snapshot=EXCLUDED.unit_cost_snapshot, discount_total=EXCLUDED.discount_total,
  line_total=EXCLUDED.line_total, returned_quantity=EXCLUDED.returned_quantity;

ON CONFLICT (id) DO UPDATE SET
  status=EXCLUDED.status, amount=EXCLUDED.amount, reference=EXCLUDED.reference,
  paid_at=EXCLUDED.paid_at, sales_order_id=EXCLUDED.sales_order_id;

ON CONFLICT DO NOTHING;

ON CONFLICT (id) DO UPDATE SET
  due_date=EXCLUDED.due_date, status=EXCLUDED.status;

ON CONFLICT (id) DO UPDATE SET
  status=EXCLUDED.status, total=EXCLUDED.total, amount_paid=EXCLUDED.amount_paid,
  notes=EXCLUDED.notes, ordered_at=EXCLUDED.ordered_at, updated_at=now();

ON CONFLICT (id) DO UPDATE SET
  quantity=EXCLUDED.quantity, received_quantity=EXCLUDED.received_quantity,
  unit_cost=EXCLUDED.unit_cost, line_total=EXCLUDED.line_total,
  wholesale_price_snapshot=EXCLUDED.wholesale_price_snapshot,
  retail_price_snapshot=EXCLUDED.retail_price_snapshot;

ON CONFLICT (id) DO UPDATE SET
  status=EXCLUDED.status, amount=EXCLUDED.amount, reference=EXCLUDED.reference,
  paid_at=EXCLUDED.paid_at, purchase_order_id=EXCLUDED.purchase_order_id;

ON CONFLICT (id) DO UPDATE SET
  name=EXCLUDED.name, category=EXCLUDED.category, amount=EXCLUDED.amount,
  payment_method=EXCLUDED.payment_method, day_of_month=EXCLUDED.day_of_month,
  starts_on=EXCLUDED.starts_on, notes=EXCLUDED.notes, active=true, updated_at=now();

ON CONFLICT (id) DO UPDATE SET
  category=EXCLUDED.category, name=EXCLUDED.name, amount=EXCLUDED.amount,
  notes=EXCLUDED.notes, incurred_on=EXCLUDED.incurred_on,
  expense_type=EXCLUDED.expense_type, payment_method=EXCLUDED.payment_method,
  recurring_expense_id=EXCLUDED.recurring_expense_id;

ON CONFLICT (id) DO UPDATE SET
  refund_total=EXCLUDED.refund_total, reason=EXCLUDED.reason, returned_at=EXCLUDED.returned_at;

ON CONFLICT (id) DO UPDATE SET
  quantity=EXCLUDED.quantity, refund_amount=EXCLUDED.refund_amount, disposition=EXCLUDED.disposition;

ON CONFLICT (id) DO UPDATE SET paid_at=EXCLUDED.paid_at, amount=EXCLUDED.amount;

ON CONFLICT (id) DO UPDATE SET snapshot=EXCLUDED.snapshot, created_at=EXCLUDED.created_at;

COMMIT;
